import { readFile, writeFile } from 'node:fs/promises';
const fileUrl = new URL('./contacts.json', import.meta.url);
const contacts = JSON.parse(await readFile(fileUrl, 'utf8'));
const updated = contacts.filter((contact) => contact.id !== 'remove-me');
await writeFile(fileUrl, JSON.stringify(updated, null, 2));
